$ErrorActionPreference='Stop';$js=@'

const finish=(o)=>{console.log(JSON.stringify(o));process.exit(0)};
setTimeout(()=>finish({status:"GLOBAL_DEADLINE"}),15000);
const id="8682F60C59EAE3EF9CF12DCE711A647B";
try{
 const tabs=await fetch("http://127.0.0.1:17447/json/list",{signal:AbortSignal.timeout(5000)}).then(r=>r.json());
 const t=tabs.find(x=>x.id===id);if(!t)finish({error:"TARGET_MISSING"});
 const ws=new WebSocket(t.webSocketDebuggerUrl);
 await Promise.race([new Promise((ok,no)=>{ws.addEventListener("open",ok,{once:true});ws.addEventListener("error",no,{once:true})}),new Promise((_,no)=>setTimeout(()=>no(new Error("NO_WS_OPEN")),4000))]);
 const exp="(()=>({title:document.title,bodyLength:document.body?.innerText?.length||0,bodyText:(document.body?.innerText||'').slice(0,11500)}))()";
 const response=await Promise.race([new Promise(ok=>{ws.addEventListener("message",e=>{try{const x=JSON.parse(e.data);if(x.id===101)ok(x)}catch{}});ws.send(JSON.stringify({id:101,method:"Runtime.evaluate",params:{expression:exp,returnByValue:true}}))}),new Promise((_,no)=>setTimeout(()=>no(new Error("NO_CDP_REPLY")),6500))]);
 ws.close();finish({status:"received",response});
}catch(e){finish({error:String(e)})}

